/* ===== v2 vendor + provider: services, subcategory suggestions, media + tagging ===== */
const mySubs=()=>{const l=D().subs.filter(s=>s.bid===ownerId()).sort((a,b)=>b.ts-a.ts);if(!l.length)return `<div class="small muted">${t('No suggestions yet.')}</div>`;return `<div class="stack" style="gap:6px"><div class="lbl small">${t('My suggestions')}</div>${l.map(s=>`<div class="row between wrap-r small"><span><b>${esc(s.en)}</b> <span class="muted">· ${esc(catName(s.main))}</span>${s.reason?`<div class="xs t2">${t('Reason')}: ${esc(s.reason)}</div>`:''}${s.mergedInto?`<div class="xs t2">${t('Merged into')}: ${esc(s.mergedInto)}</div>`:''}</span>${subBadge(s.status)}</div>`).join('')}</div>`};
const subBadge=s=>({pending:`<span class="badge warn">⏳ ${t('Pending')}</span>`,approved:`<span class="badge ok">✓ ${t('Approved')}</span>`,rejected:`<span class="badge bad">✕ ${t('Rejected')}</span>`,merged:`<span class="badge info">⇄ ${t('Merged')}</span>`})[s]||s;
function subSheet(v={}){const mains=[...D().cats,...D().scats];const own=ent(ownerId())||{cat:'grocery'};const main=v.main||own.cat;const sim=similarSub(main,v.en);
 sheet(`<div class="row between"><h3>${t('Suggest a subcategory')}</h3><button class="iconbtn" data-act="closeSheet" aria-label="${t('Close')}">${ic('x')}</button></div><p class="small t2">${t('Main categories are fixed. Tell us which subcategory is missing and an admin will review it.')}</p><form data-form="subs" class="stack" style="margin-top:10px">${field('Main category','main',main,{type:'select',opts:mains.map(c=>[c.id,nm(c)])})}<div class="field"><label for="f_en">${t('Subcategory name (English)')} *</label><input class="input" id="f_en" name="en" required value="${esc(v.en||'')}" data-in="subq" autocomplete="off"></div>${field('Name in Hindi (optional)','hi',v.hi||'')}${field('Why is it needed? (optional)','note',v.note||'',{type:'textarea'})}<div id="subdup">${dupHtml(main,v.en||'')}</div><button class="btn p block" id="subgo" ${sim&&sim.en.toLowerCase()===(v.en||'').trim().toLowerCase()?'disabled':''}>${sim&&sim.en.toLowerCase()!==(v.en||'').trim().toLowerCase()?t('Suggest anyway'):t('Send suggestion')}</button></form>`,{label:'Suggest a subcategory'})}
const dupHtml=(main,en)=>{const s=similarSub(main,en);if(!s)return en.trim().length>=3?`<div class="small" style="color:var(--success)">✓ ${t('No similar subcategory found.')}</div>`:'';const exact=s.en.toLowerCase()===en.trim().toLowerCase();return alertBox(exact?'bad':'warn',`<b>${t('Similar subcategory already exists')}: ${esc(s.en)}</b> <span class="xs">(${t(s.st==='pending'?'Pending':'Approved')})</span><br><span class="small">${exact?t('This exact name already exists. Please use it.'):t('Check it before sending a new one.')}</span>`,'info')};
A.subSuggest=()=>subSheet();
INP.subq=(v,el)=>{const f=el.form,main=f.elements.main.value,sim=similarSub(main,v);$('#subdup').innerHTML=dupHtml(main,v);const b=$('#subgo');if(b){const exact=sim&&sim.en.toLowerCase()===v.trim().toLowerCase();b.disabled=!!exact;b.textContent=sim&&!exact?t('Suggest anyway'):t('Send suggestion')}};
document.addEventListener('change',e=>{if(e.target.name==='main'&&e.target.closest('form[data-form=subs]')){const f=e.target.form;INP.subq(f.elements.en.value,f.elements.en)}});
F.subs=d=>{if(similarSub(d.main,d.en)&&similarSub(d.main,d.en).en.toLowerCase()===d.en.trim().toLowerCase())return;const o=ent(ownerId()),me=S.role==='admin'||S.role==='super';const sg={id:rid('sb'),main:d.main,en:d.en.trim(),hi:d.hi||'',note:d.note||'',status:'pending',by:me?(S.role==='super'?'Super Admin':curAdmin().name):nm(o.name),byRole:me?'admin':MYROLE(),bid:me?'':ownerId(),ts:Date.now()};D().subs.unshift(sg);notify('admin','Subcategory suggestion',sg.en+' · '+catName(sg.main)+' · by '+sg.by,'asubs','sys');save();closeSheet();render(true);toast(t('Suggestion sent for review'),'send')};
/* services manager */
V.vservices=()=>{if(!canAct(MYROLE()))return lockedMsg(MYROLE());const x=vb(),l=x.services||[];
 return `<div class="stack"><div class="row between wrap-r"><h1>${t('Services')}</h1><button class="btn p sm" data-act="svEdit" data-id="">${ic('plus',16)} ${t('Add service')}</button></div>${alertBox('info',t('Services are shown on your public page. Customers can send an enquiry for any service. Booking and payment can be added later.'))}${l.length?`<div class="stack">${l.map(s=>`<div class="card pad row wrap-r" style="align-items:flex-start"><div class="grow"><b>${esc(s.n)}</b>${s.desc?`<div class="small t2">${esc(s.desc)}</div>`:''}<span class="badge neu" style="margin-top:4px">${esc(s.p)}</span></div><div class="row"><button class="btn g sm" data-act="svEdit" data-id="${s.id}">${t('Edit')}</button><button class="btn t sm" data-act="svDel" data-id="${s.id}" aria-label="${t('Delete')} ${esc(s.n)}">${ic('trash',16)}</button></div></div>`).join('')}</div>`:empty('🔧','No services yet','Add the services you offer. Customers will be able to send enquiries.','<button class="btn p" data-act="svEdit" data-id="">'+t('Add your first service')+'</button>')}</div>`};
A.svEdit=el=>{const x=vb(),s=(x.services||[]).find(a=>a.id===el.dataset.id)||{id:'',n:'',p:'',desc:''};sheet(`<h3>${s.id?t('Edit service'):t('Add service')}</h3><form data-form="svc" class="stack" style="margin-top:10px"><input type="hidden" name="id" value="${s.id}">${field('Service name','n',s.n,{req:1})}${field('Price or “starts from”','p',s.p,{req:1,ph:'e.g. from ₹499'})}${field('Description','desc',s.desc,{type:'textarea'})}<button class="btn p">${t('Save service')}</button></form>`)};
F.svc=d=>{const x=vb();x.services=x.services||[];let s=x.services.find(a=>a.id===d.id);if(s)Object.assign(s,{n:d.n,p:d.p,desc:d.desc,from:fromNum(d.p)});else x.services.push({id:x.id+'-sv'+Date.now().toString(36),n:d.n,p:d.p,desc:d.desc,from:fromNum(d.p)});save();closeSheet();render(true);toast(t('Service saved'),'check')};
A.svDel=el=>confirmBox(t('Delete this service?'),t('Videos that tag it will lose the tag.'),t('Delete'),()=>{const x=vb();x.services=x.services.filter(a=>a.id!==el.dataset.id);(x.media||[]).forEach(m=>m.tags=(m.tags||[]).filter(t_=>t_!==el.dataset.id));save();render(true);toast(t('Deleted'),'trash')},true);
/* product editor with media sorter */
V.vprod=id=>{if(!canAct(MYROLE()))return lockedMsg(MYROLE());const isNew=id==='new',p=isNew?{id:'',name:{en:'',hi:''},price:'',mrp:'',unit:'1 pc',sku:'',stock:10,low:5,variants:[],tags:[],sub:'',desc:'',avail:true,featured:false,brand:'',media:[]}:prod(id);if(!p||(!isNew&&p.bid!==ownerId()))return V.nf();
 if(UI.pmId!==id){UI.pmId=id;UI.pm=JSON.parse(JSON.stringify(p.media||[]))}const own=vb(),subs=[...new Set([...subsFor(own.cat),...D().products.filter(x=>x.bid===ownerId()).map(x=>x.sub)])].sort();
 return `<div class="stack-lg"><a class="btn t sm" href="#${RT('vproducts')}" style="justify-self:start">${ic('cl',16)} ${t('Products')}</a><h1>${isNew?t('Add product'):t('Edit product')}</h1><form data-form="vprod" class="cols2"><input type="hidden" name="id" value="${p.id}"><div class="stack"><div class="card pad stack">${field('Product name (English)','en',p.name.en,{req:1})}${field('Product name (Hindi)','hi',p.name.hi)}${field('Description','desc',p.desc,{type:'textarea'})}<div class="grid g2">${field('Subcategory','sub',p.sub||subs[0]||'',{type:'select',opts:(subs.length?subs:['Items']).map(s=>[s,s])})}${field('Brand','brand',p.brand||'')}</div><button type="button" class="btn t sm" style="justify-self:start" data-act="subSuggest">${ic('plus',14)} ${t('Suggest a new subcategory')}</button></div><div class="card pad stack"><div class="grid g2">${field('Price (₹)','price',p.price,{req:1,type:'number',min:0,step:'0.01',im:'decimal'})}${field('MRP (₹)','mrp',p.mrp,{type:'number',min:0,step:'0.01'})}${field('Unit','unit',p.unit,{ph:'e.g. 1 kg'})}${field('SKU','sku',p.sku)}${field('Stock','stock',p.stock,{type:'number',min:0})}${field('Low-stock alert at','low',p.low,{type:'number',min:0})}</div>${field('Variants (comma separated)','variants',p.variants.join(', '),{ph:'5 kg, 10 kg'})}${field('Tags','tags',p.tags.join(', '),{ph:'fresh, local'})}</div></div>
 <div class="stack"><div class="card pad stack" id="pmsort"><h3>${t('Media: photos, YouTube and Instagram')}</h3>${pmSorter()}</div>${mediaConsent(isNew?vb().mediaDefault!==false:p.inGallery!==false,'tgform')}<div class="card pad stack">${toggle('avail',p.avail,'Available for sale','tgform')}<input type="hidden" name="avail" value="${p.avail?1:0}" id="h_avail">${toggle('featured',p.featured,'Featured product','tgform')}<input type="hidden" name="featured" value="${p.featured?1:0}" id="h_featured"></div>${!isNew?`<div class="card pad stack"><h3>${t('Shareable link')}</h3><input class="input" readonly value="${esc(shareUrl('prod-'+p.id))}" aria-label="Link"><div class="row"><button type="button" class="btn g grow" data-act="copy" data-v="${esc(shareUrl('prod-'+p.id))}">${ic('copy',16)} ${t('Copy')}</button><button type="button" class="btn s grow" data-act="share" data-id="${p.id}">${ic('share',16)} ${t('Share')}</button></div></div>`:''}<button class="btn p block">${t('Save product')}</button></div></form></div>`};
function pmSorter(){const l=UI.pm||[];return `<div class="stack" style="gap:8px">${l.length?l.map((m,i)=>`<div class="card pad row">${pmArt(m,'mini')}<div class="grow small"><b>${m.t==='img'?t('Photo')+' '+(i+1):esc(m.title||mLabel(m))}</b><div class="xs muted">${m.t==='img'?'':mLabel(m)+' · '+mKind(m)}</div></div>${m.t!=='img'?`<button type="button" class="btn g sm" data-act="pmPrev" data-i="${i}">${ic('eye',14)} ${t('Preview')}</button>`:''}<button type="button" class="iconbtn" style="width:40px;height:40px" data-act="pmMove" data-i="${i}" data-d="-1" ${i?'':'disabled'} aria-label="${t('Move up')}">${ic('cu',16)}</button><button type="button" class="iconbtn" style="width:40px;height:40px" data-act="pmMove" data-i="${i}" data-d="1" ${i<l.length-1?'':'disabled'} aria-label="${t('Move down')}">${ic('cd',16)}</button><button type="button" class="iconbtn" style="width:40px;height:40px" data-act="pmDel" data-i="${i}" aria-label="${t('Remove')}">${ic('trash',16)}</button></div>`).join(''):`<div class="small muted">${t('No media yet.')}</div>`}<div class="drop"><button type="button" class="btn g sm" data-act="pmImg">${ic('camera',16)} ${t('Add photo')}</button></div>
 <div class="field"><label for="pmurl">${t('Paste a YouTube or Instagram link')}</label><div class="row"><input class="input" id="pmurl" data-in="pmurl" placeholder="https://youtu.be/…" autocomplete="off"><button type="button" class="btn p" data-act="pmAdd">${t('Add')}</button></div><div id="pmv" class="small"></div></div></div>`}
const redrawPm=()=>{const b=$('#pmsort');if(b)b.innerHTML=`<h3>${t('Media: photos, YouTube and Instagram')}</h3>`+pmSorter()};
A.pmMove=el=>{const l=UI.pm,i=+el.dataset.i,j=i+ +el.dataset.d;[l[i],l[j]]=[l[j],l[i]];redrawPm()};A.pmDel=el=>{UI.pm.splice(+el.dataset.i,1);redrawPm()};
A.pmImg=()=>{const e=['📸','🖼️','📦','✨'][UI.pm.length%4];UI.pm.push({t:'img',e,h:(UI.pm.length*40+30)%360});redrawPm();toast(t('Photo added (demo)'),'camera')};
function embedPrev(v){const r=parseEmbed(v);if(!v.trim())return '';return r.ok?`<div class="card pad row" style="margin-top:6px"><div class="mini art" style="--h:${r.t==='yt'?0:330}">${r.t==='yt'?'▶️':'📷'}</div><div class="grow"><b>${mLabel(r)} ${r.reel?t('reel'):t('video')}</b><div class="xs muted truncate">${esc(v)}</div></div><span class="badge ok">✓ ${t('Valid')}</span></div>`:`<div class="errmsg" role="alert" style="margin-top:6px">${t(r.err)}</div>`}
INP.pmurl=v=>{$('#pmv').innerHTML=embedPrev(v)};
A.pmAdd=()=>{const i=$('#pmurl'),r=parseEmbed(i.value);if(!r.ok){$('#pmv').innerHTML=embedPrev(i.value||' ')||`<div class="errmsg" role="alert">${t('Paste a YouTube or Instagram link.')}</div>`;return}UI.pm.push({t:r.t,id:rid('pm'),vid:r.vid,url:r.url,reel:r.reel,title:(r.t==='yt'?'YouTube':'Instagram')+(r.reel?' reel':' video')});redrawPm();toast(t('Added'),'check')};
A.pmPrev=el=>{const m=UI.pm[+el.dataset.i];sheet(`<div class="row between"><b>${t('Preview')}</b><button class="iconbtn" data-act="closeSheet" aria-label="${t('Close')}">${ic('x')}</button></div><div class="art w" style="margin-top:10px;position:relative;--h:${m.t==='yt'?0:330}"><iframe title="preview" src="${embedSrc(m)}" loading="lazy" style="position:absolute;inset:0;width:100%;height:100%;border:0"></iframe></div><a class="btn g block" style="margin-top:10px" target="_blank" rel="noopener" href="${esc(extUrl(m))}">${t('Open in')} ${mLabel(m)}</a>`,{wide:true})};
F.vprod=d=>{const list=s=>(s||'').split(',').map(x=>x.trim()).filter(Boolean);const b=vb();let p=d.id?prod(d.id):null;const base={name:{en:d.en,hi:d.hi},desc:d.desc,sub:d.sub,brand:d.brand,price:+d.price,mrp:+d.mrp||+d.price,unit:d.unit,sku:d.sku||b.id.toUpperCase()+'-X',stock:+d.stock,low:+d.low,variants:list(d.variants),tags:list(d.tags),avail:d.avail==='1',featured:d.featured==='1',inGallery:d.inGallery==='1',media:UI.pm&&UI.pm.length?UI.pm:defImgs({emoji:catOf(b.cat).e,hue:b.hue})};
 if(p)Object.assign(p,base);else{p={id:'p'+(D().products.reduce((a,x)=>Math.max(a,+x.id.slice(1)),0)+1),bid:b.id,cat:b.cat,emoji:catOf(b.cat).e,hue:b.hue,specs:[['Pack size',base.unit]],status:'active',...base};D().products.push(p)}UI.pmId=null;save();toast(t('Product saved'),'check');go(RT('vprod')+'-'+p.id)};
/* media manager with tagging */
V.vmedia=()=>{if(!canAct(MYROLE()))return lockedMsg(MYROLE());const b=vb(),med=b.media||[];
 return `<div class="stack-lg"><h1>${t('Gallery & media')}</h1><div class="card pad stack"><h3>${t('Photos')}</h3>${uploader('Add photos (4:3)')}<div class="grid g3">${b.gallery.map((g,i)=>`<div class="stack" style="gap:4px">${art(g,b.hue+i*20,'f')}<div class="row"><button class="iconbtn" style="width:36px;height:36px" data-act="gmove" data-i="${i}" data-d="-1" aria-label="${t('Move left')}" ${i?'':'disabled'}>${ic('cl',16)}</button><button class="iconbtn" style="width:36px;height:36px" data-act="gmove" data-i="${i}" data-d="1" aria-label="${t('Move right')}" ${i<b.gallery.length-1?'':'disabled'}>${ic('cr',16)}</button><button class="iconbtn" style="width:36px;height:36px" data-act="gdel" data-i="${i}" aria-label="${t('Delete')}">${ic('trash',16)}</button></div></div>`).join('')}</div></div>
 <div class="card pad stack"><h3>${t('Videos & reels')}</h3><p class="small t2">${t('Paste a YouTube video, YouTube Shorts or Instagram reel link. Customers can play it on your page.')}</p><form data-form="mediaAdd" class="stack"><div class="field"><label for="mu">${t('Link')}</label><input class="input" id="mu" name="url" data-in="mediaUrl" placeholder="https://www.youtube.com/watch?v=…" required autocomplete="off"></div><div id="mprev"></div>${field('Title','title','',{ph:'e.g. Store tour'})}<button class="btn p">${ic('plus',16)} ${t('Add video or reel')}</button></form></div>
 ${med.length?med.map((m,i)=>`<div class="card pad stack"><div class="row">${art(m.t==='yt'?'▶️':'📷',m.t==='yt'?0:330,'mini')}<div class="grow"><b>${esc(m.title)}</b><div class="small t2">${mLabel(m)} · ${mKind(m)==='reel'?t('Reel'):t('Video')}</div></div><button class="iconbtn" style="width:40px;height:40px" data-act="mvMove" data-i="${i}" data-d="-1" ${i?'':'disabled'} aria-label="${t('Move up')}">${ic('cu',16)}</button><button class="iconbtn" style="width:40px;height:40px" data-act="mvMove" data-i="${i}" data-d="1" ${i<med.length-1?'':'disabled'} aria-label="${t('Move down')}">${ic('cd',16)}</button></div><div class="row wrap-r" style="gap:6px"><b class="small">${t('Tagged')}:</b>${(m.tags||[]).map(tagItem).filter(Boolean).map(i=>`<span class="chip" style="min-height:32px">${esc(i.name)}</span>`).join('')||`<span class="muted small">${t('Nothing tagged yet')}</span>`}</div><div class="row wrap-r"><button class="btn o sm" data-act="tagPick" data-i="${i}">${ic('tag',14)} ${t('Tag products or services')}</button><button class="btn g sm" data-act="playMedia" data-o="${b.id}" data-m="${m.id}">${ic('eye',14)} ${t('Preview')}</button><button class="btn t sm" data-act="mvDel" data-i="${i}" style="color:var(--error)">${ic('trash',14)} ${t('Remove')}</button></div></div>`).join(''):empty('🎬','No videos or reels yet','Paste a link above to add your first one.')}</div>`};
INP.mediaUrl=v=>{$('#mprev').innerHTML=embedPrev(v)};
F.mediaAdd=d=>{const r=parseEmbed(d.url);if(!r.ok){$('#mprev').innerHTML=embedPrev(d.url);toast(t(r.err),'alert');return}const b=vb();b.media=b.media||[];b.media.push({id:rid('m'),t:r.t,vid:r.vid,url:r.url,reel:r.reel,title:d.title||(mLabel(r)+(r.reel?' reel':' video')),tags:[]});save();render(true);toast(t('Added. Now tag your products.'),'check')};
A.mvMove=el=>{const l=vb().media,i=+el.dataset.i,j=i+ +el.dataset.d;[l[i],l[j]]=[l[j],l[i]];save();render(true)};A.mvDel=el=>confirmBox(t('Remove this video?'),t('Hearts saved by customers will also disappear.'),t('Remove'),()=>{const b=vb(),m=b.media[+el.dataset.i];S.hearts=S.hearts.filter(h=>!(h.owner===b.id&&h.mid===m.id));b.media.splice(+el.dataset.i,1);save();render(true)},true);
function tagList(q){const b=vb(),items=[...D().products.filter(p=>p.bid===b.id).map(p=>({id:p.id,n:nm(p.name),k:'Product',sub:inr(p.price)})),...(b.services||[]).map(s=>({id:s.id,n:s.n,k:'Service',sub:s.p}))].filter(x=>!q||x.n.toLowerCase().includes(q.toLowerCase()));const sel=UI.tagSel||[];return items.length?items.map(x=>`<label class="check card pad"><input type="checkbox" ${sel.includes(x.id)?'checked':''} data-chg="tagSel" data-id="${x.id}" style="accent-color:var(--primary)"><span class="grow"><b class="small">${esc(x.n)}</b><span class="xs muted" style="display:block">${t(x.k)} · ${esc(x.sub)}</span></span></label>`).join(''):empty('🔎','No match','Try another name.')}
A.tagPick=el=>{const m=vb().media[+el.dataset.i];UI.tagI=+el.dataset.i;UI.tagSel=[...(m.tags||[])];sheet(`<div class="row between"><h3>${t('Tag products or services')}</h3><button class="iconbtn" data-act="closeSheet" aria-label="${t('Close')}">${ic('x')}</button></div><p class="small t2">${esc(m.title)}</p><div class="searchbar" style="margin:10px 0">${ic('search',18)}<input data-in="tagq" placeholder="${t('Search your products and services')}" aria-label="${t('Search')}"></div><div id="taglist" class="stack" style="max-height:46vh;overflow:auto">${tagList('')}</div><button class="btn p block" style="margin-top:10px" data-act="tagSave">${t('Save tags')}</button>`,{label:'Tag picker'})};
INP.tagq=v=>{$('#taglist').innerHTML=tagList(v)};CH.tagSel=el=>{const s=UI.tagSel,id=el.dataset.id;UI.tagSel=el.checked?[...new Set([...s,id])]:s.filter(x=>x!==id)};
A.tagSave=()=>{vb().media[UI.tagI].tags=[...UI.tagSel];save();closeSheet();render(true);toast(t('Tags saved'),'tag')};
/* provider aliases */
V.sproducts=V.vproducts;V.sprod=V.vprod;V.sservices=V.vservices;V.smedia=V.vmedia;V.sorders=V.vorders;V.sorder=V.vorder;V.venq=V.senq;
